function bmrAll(w){ const P=prof(), f=P.sex==='f', F=w*(1-clamp(+P.bf||28,3,60)/100);
  return {ffm:F,mifflin:Math.round(10*w+6.25*P.h-5*P.age+(f?-161:5)),harris:Math.round(f?447.593+9.247*w+3.098*P.h-4.33*P.age:88.362+13.397*w+4.799*P.h-5.677*P.age),
    cunningham:Math.round(500+22*F),katch:Math.round(370+21.6*F)}; }
/* pauzele de dietă din programul original: săptămânile 1–2 ale ciclului în deficit, 3–4 la menținere */
function nPhase(){ if(prof().dietBreak===false) return {cut:true,label:'Deficit',sub:'deficit continuu'};
  const nx=nextDay(), w=nx?nx.w:0;
  return w<2?{cut:true,label:'Deficit',sub:'săptămâna '+(w+1)+' din 2 de deficit'}:{cut:false,label:'Menținere',sub:'săptămâna '+(w-1)+' din 2 de menținere'}; }
/* necesarul măsurat: aportul mediu din zilele notate complet minus energia echivalentă variației greutății (regresie pe 21 de zile) */
function tdeeMeasured(){
  const tk=todayKey(), ks=[]; for(let i=1;i<=21;i++){ const k=dayShift(tk,-i), t=dayTotals(k); if(mlogDay(k).length>=3&&t.k>=1500) ks.push(t.k); }
  const a=wList().filter(x=>x.d>=dayShift(tk,-21)&&x.d<=tk), res={ok:false,days:ks.length,weighs:a.length};
  if(ks.length<7||a.length<8) return res;
  const xs=a.map(p=>daysBetween(a[0].d,p.d)), mx=xs.reduce((s,x)=>s+x,0)/xs.length, my=a.reduce((s,p)=>s+p.w,0)/a.length;
  let cov=0,vr=0; xs.forEach((x,i)=>{ cov+=(x-mx)*(a[i].w-my); vr+=(x-mx)*(x-mx); }); if(!vr) return res;
  const slope=cov/vr, intake=ks.reduce((s,x)=>s+x,0)/ks.length, tdee=Math.round(intake-slope*7700);
  if(tdee<1500||tdee>7000) return Object.assign(res,{odd:true});
  return {ok:true,tdee,intake:Math.round(intake),perWeek:slope*7,days:ks.length,weighs:a.length};
}
function targets(){
  const P=prof(), ws=wStats(), w=ws?ws.a7:P.startW, A=bmrAll(w), eq=A[P.eq]!=null?P.eq:'mifflin', bmr=A[eq];
  const est=Math.round(bmr*(+P.act||1.55)), ms=tdeeMeasured(), useM=ms.ok&&P.useMeasured!==false, tdee=useM?ms.tdee:est, ph=nPhase();
  const def=ph.cut?(+P.def||600):0, auto=Math.max(Math.round(bmr*1.1/50)*50,Math.round((tdee-def)/50)*50), kcal=+P.kcalT||auto;
  const p=+P.protT||Math.round((P.goalW||w)*2); let f=Math.round(w*.7), c=Math.round((kcal-p*4-f*9)/4);
  if(c<80){ f=Math.max(Math.round(w*.6),Math.round((kcal-p*4-320)/9)); c=Math.max(0,Math.round((kcal-p*4-f*9)/4)); }
  return {kcal,p,f,c,water:+P.waterT||3500,bmr,tdee,est,measured:useM,ms,auto,manual:!!P.kcalT,phase:ph,eq,def,A};
}
/* planul de mese: pentru fiecare masă, rețetele cele mai apropiate de ținta ei; aceeași zi dă același plan până îl schimbi */
const mealOK=m=>(!S.mf.port||m[6]===1)&&(!S.mf.cold||m[7]===1);
function seedRand(str){ let h=2166136261>>>0; for(let i=0;i<str.length;i++){ h^=str.charCodeAt(i); h=Math.imul(h,16777619)>>>0; }
  return ()=>{ h^=h<<13; h>>>=0; h^=h>>>17; h^=h<<5; h>>>=0; return h/4294967296; }; }
function slotCands(si,tg){ const [,cat,share]=MSLOTS[si], kT=tg.kcal*share, pT=tg.p*share;
  return MEALS.map((m,i)=>({m,i})).filter(x=>x.m[0]===cat&&mealOK(x.m)).map(x=>Object.assign(x,{sc:Math.abs(x.m[2]-kT)/kT+Math.max(0,pT-x.m[3])/pT*.6})).sort((a,b)=>a.sc-b.sc); }
/* încearcă 40 de combinații din cele mai potrivite rețete pe fiecare masă și o păstrează pe cea mai apropiată de totalul zilei */
const PLC={};
function planFor(k,tg){ tg=tg||targets(); const sv=(S.mplan||{})[k]||{}, key=k+'|'+(sv.s||0)+'|'+(S.mf.port?1:0)+(S.mf.cold?1:0)+'|'+tg.kcal+'|'+tg.p+'|'+JSON.stringify(sv.m||[]);
  if(PLC[key]) return PLC[key].slice();
  const rnd=seedRand(key), cands=MSLOTS.map((_,si)=>sv.m&&sv.m[si]!=null&&MEALS[sv.m[si]]?[sv.m[si]]:slotCands(si,tg).slice(0,7).map(x=>x.i));
  let best=null,bs=Infinity;
  for(let t=0;t<40;t++){ const used=new Set(cands.filter(c=>c.length===1).map(c=>c[0]));
    const pick=cands.map(c=>{ if(c.length===1) return c[0]; const free=c.filter(i=>!used.has(i)); if(!free.length) return null; const i=free[Math.floor(rnd()*free.length)]; used.add(i); return i; });
    const tot=pick.reduce((a,i)=>i==null?a:{k:a.k+MEALS[i][2],p:a.p+MEALS[i][3]},{k:0,p:0}), sc=Math.abs(tot.k-tg.kcal)/tg.kcal+Math.max(0,tg.p-tot.p)/tg.p*.5;
    if(sc<bs){ bs=sc; best=pick; } }
  PLC[key]=best; return best.slice(); }
async function planSet(k,si,mi){ const mp=Object.assign({},S.mplan), cur=planFor(k), sv=Object.assign({},mp[k]||{}); sv.m=cur.slice(); if(si!=null) sv.m[si]=mi; mp[k]=sv;
  Object.keys(mp).forEach(d=>{ if(d<dayShift(todayKey(),-30)) delete mp[d]; }); await save('mplan',mp); }
